#include <stdio.h>
#include <stdlib.h>

int main() {
    int n = 3;
    int *p = (int *)malloc(sizeof(int) * n);
    int sum = 0;

    if (p == NULL) {
        return 1;
    }

    for (int i = 0; i < n; i++) {
        p[i] = (i + 1) * 5;
        sum += p[i];
    }

    printf("%d\n", sum);

    free(p);
    p = NULL;
    return 0;
}
